def solve_a(N):
    a = {}
    a[1] = 1
    a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # Need a_{n-1} first
        if n - 1 not in a:
            # This should not happen if we iterate correctly
            print(f"Error: a_{n-1} not computed.")
            return {}

        a_n_minus_1 = a[n-1]

        # Arguments for the sum: a_{a_{n-1}} and a_{n - a_{n-1}}
        arg1 = a_n_minus_1
        arg2 = n - a_n_minus_1

        # Both arguments must be positive integers and less than n
        if arg1 <= 0 or arg2 <= 0 or arg1 >= n or arg2 >= n:
            print(f"Error: Invalid arguments for a_{n}. Arg1={arg1}, Arg2={arg2}, n={n}")
            return {}

        if arg1 not in a or arg2 not in a:
            print(f"Error: Dependency missing for a_{n}. Missing a_{arg1} or a_{arg2}.")
            return {}

        a_n = a[arg1] + a[arg2]
        a[n] = a_n

    return a

# We need to check up to n=64, so let's compute up to a reasonable limit first, like 32.
N_test = 32
results = solve_a(N_test)

# Check a_{2^k} for k=1 to 5 (n=2, 4, 8, 16, 32)
powers_of_2 = [2**k for k in range(1, 6)]
print("--- Values of a_{2^k} ---")
for n in powers_of_2:
    if n in results:
        print(f"a_{n} = {results[n]}")
    else:
        print(f"a_{n} not computed.")

# If successful, compute up to 64
N_full = 64
results_full = solve_a(N_full)

# Check a_{2^k} for k=6 (n=64)
print("\n--- Value of a_{64} ---")
if 64 in results_full:
    print(f"a_{64} = {results_full[64]}")
else:
    print("a_{64} not computed.")
